:root {
  --calendar-dialog-gap: calc(var(--space-base) + var(--space-step));
  --calendar-dialog-row-padding-inline: calc(var(--space-base) + 2 * var(--space-step));
  --calendar-dialog-row-column-gap: var(--calendar-dialog-gap);
  --calendar-dialog-row-content-gap: var(--space-step);
  --calendar-dialog-row-expand-button-padding-inline-start: var(--calendar-dialog-gap);
  --calendar-dialog-expanded-row-content-gap: var(--space-base);
  --calendar-dialog-expanded-row-padding-block: calc(var(--space-base) + 2 * var(--space-step));
  --calendar-border-radius: calc(2 * var(--space-step));
  --calendar-dialog-top-bar-height: var(--space-base);
  --calendar-dialog-title-bar-padding-block: var(--calendar-dialog-gap);
}

[is="calendar-dialog"] {
  border-radius: var(--calendar-border-radius);
  border: 1px solid var(--color-surface-border);
  box-shadow: 0 2px 24px rgba(0, 0, 0, 0.15);
  margin: 0;
  padding: 0;
  inline-size: 424px;
  max-block-size: calc(100vh - 8 * var(--space-step));
  z-index: 999;
  box-sizing: border-box;
  background-color: var(--color-surface-base);

  .footer {
    block-size: 50px;
    padding-inline: 12px;
    padding-block: 9px;
    box-sizing: border-box;
    border-block-start: 1px solid var(--color-surface-border);

    &:has(calendar-dialog-acceptance[hidden]) {
      display: none;
    }
  }
}

.titlebar {
  --calendar-bar-color-fallback: #1373d9;
  position: relative;
  display: flex;
  align-items: flex-start;
  flex-direction: column;
  overflow: hidden;
  padding: calc(var(--calendar-dialog-title-bar-padding-block) + var(--calendar-dialog-top-bar-height)) var(--calendar-dialog-row-padding-inline)
    var(--calendar-dialog-title-bar-padding-block);
  gap: 4px;

  &::before {
    border-radius: var(--calendar-border-radius) var(--calendar-border-radius) 0 0;
    content: "";
    position: absolute;
    inset-block-start: 0;
    inset-inline: 0;
    block-size: var(--calendar-dialog-top-bar-height);
    background: var(--calendar-bar-color, var(--calendar-bar-color-fallback));
  }

  & .titlebar-row {
    position: relative;
    min-inline-size: 100%;
    display: flex;
    align-items: center;
    gap: calc(3 * var(--space-step));
  }

  & .calendar-name {
    flex: 1;

    &::before {
      content: "";
      background: var(--calendar-bar-color, var(--calendar-bar-color-fallback));
      inline-size: 9px;
      block-size: 9px;
      margin-inline-end: 9px;
      display: inline-block;
      border-radius: 9px;
    }
  }

  & .calendar-dialog-title {
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    display: -webkit-box;
    flex: 1;
    font-size: 1.3636rem;
    font-weight: 500;
    margin: 0;
    overflow: hidden;
    padding-inline: 0;
    text-overflow: ellipsis;
  }

  & .title-button-container {
    display: inline-flex;
    margin-inline-end: calc(2px - var(--button-padding));
    gap: 1px;
    flex: 0;
  }
}

.row-label {
  font-size: 1rem;
  font-weight: 700;
}

.icon-date-time {
  content: var(--icon-date-time-sm);
}

.icon-recurrence {
  content: var(--icon-recurrence);
  -moz-context-properties: stroke;
  stroke: currentColor;
}

.icon-location {
  content: var(--icon-globe);
}

.icon-reminder {
  content: var(--icon-bell);
}

